using System;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;

public static class Snippet
{
	public static System.String WeatherGet()
    {
        string apiKey = "59216a1bdfeef46a6518db61779c85a9";
        string city = "Kumamoto,jp";
        string url = "https://api.openweathermap.org/data/2.5/weather?q=" + city + "&appid=" + apiKey + "&units=metric&lang=ja";

        try
        {
            using (WebClient client = new WebClient())
            {
                client.Encoding = Encoding.UTF8;
                string utf8Json = client.DownloadString(url);

                var idMatch = Regex.Match(utf8Json, @"""id"":(\d+)");
                var tempMatch = Regex.Match(utf8Json, @"""temp"":([\d\.]+)");

                string idStr = idMatch.Success ? idMatch.Groups[1].Value : "不明";
                string temp = tempMatch.Success ? tempMatch.Groups[1].Value : "不明";

                int id = 0;
                if (!int.TryParse(idStr, out id))
                {
                    id = 0; // パース失敗時は0にする
                }

                string category = GetWeatherCategory(id);

                string result = string.Format("天気ID: {0}, 天気: {1}, 気温: {2}℃", idStr, category, temp);

                byte[] shiftJisBytes = Encoding.GetEncoding("shift_jis").GetBytes(result);
                string shiftJisString = Encoding.GetEncoding("shift_jis").GetString(shiftJisBytes);

                return shiftJisString;
            }
        }
        catch (Exception ex)
        {
            string err = "取得失敗: " + ex.Message;
            byte[] shiftJisBytes = Encoding.GetEncoding("shift_jis").GetBytes(err);
            return Encoding.GetEncoding("shift_jis").GetString(shiftJisBytes);
        }
    }

    private static string GetWeatherCategory(int id)
    {
        if (id >= 800 && id <= 803)
            return "晴れ";
        else if (id == 804)
            return "曇り";
        else if ((id >= 500 && id <= 531) || (id >= 300 && id <= 321))
            return "雨";
        else if (id >= 200 && id <= 232)
            return "雷雨";
        else if (id >= 600 && id <= 622)
            return "雪";
        else
            return "その他";
    }
}

using System;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;

public static class Snippet
{
	public static System.String GetWeather()
   {
        string apiKey = "59216a1bdfeef46a6518db61779c85a9";
        string city = "Kumamoto,jp";

        string weatherUrl = "https://api.open-meteo.com/v1/forecast?latitude=32.79004&longitude=130.71618&daily=weathercode&timezone=Asia%2FTokyo";
        int weatherCode = -1;
        string weatherCategory = "不明";
        int weatherId = 0;

        try
        {
            using (WebClient client = new WebClient())
            {
                client.Encoding = Encoding.UTF8;
                string json = client.DownloadString(weatherUrl);
                Match codeMatch = Regex.Match(json, @"""weathercode"":\[(\d+)");
                if (codeMatch.Success)
                {
                    weatherCode = int.Parse(codeMatch.Groups[1].Value);
                    weatherCategory = GetWeatherCategory(weatherCode, out weatherId);
                }
            }
        }
        catch
        {
            return ToShiftJis("天気コードの取得に失敗しました");
        }

        string temp = "未取得";
        string tempUrl = "https://api.openweathermap.org/data/2.5/weather?q=" + city + "&appid=" + apiKey + "&units=metric&lang=ja";

        try
        {
            using (WebClient client = new WebClient())
            {
                client.Encoding = Encoding.UTF8;
                string json = client.DownloadString(tempUrl);
                Match tempMatch = Regex.Match(json, @"""temp"":([-]?\d+(\.\d+)?)");
                if (tempMatch.Success)
                {
                    temp = tempMatch.Groups[1].Value + "℃";
                }
            }
        }
        catch
        {
            temp = "気温取得失敗";
        }

        string result = string.Format("天気ID: {0}, 天気: {1}, 気温: {2}", weatherId, weatherCategory, temp);
        return ToShiftJis(result);
    }

    private static string GetWeatherCategory(int code, out int id)
    {
        if (code == 0) { id = 1; return "晴れ"; }
        else if (code <= 3) { id = 2; return "曇り"; }
        else if (code >= 45 && code <= 48) { id = 3; return "霧"; }
        else if (code >= 51 && code <= 67) { id = 4; return "霧雨"; }
        else if (code >= 71 && code <= 77) { id = 5; return "雪"; }
        else if (code >= 80 && code <= 82) { id = 6; return "雨"; }
        else if (code >= 95 && code <= 99) { id = 7; return "雷雨"; }
        else { id = 0; return "不明"; }
    }

    private static string ToShiftJis(string text)
    {
        byte[] bytes = Encoding.GetEncoding("shift_jis").GetBytes(text);
        return Encoding.GetEncoding("shift_jis").GetString(bytes);
    }
}

using System;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;

public static class Snippet
{
	public static System.String GetWeather()
    {
        string apiKey = "59216a1bdfeef46a6518db61779c85a9";
        string city = "Kumamoto,jp";

        string weatherUrl = "https://api.open-meteo.com/v1/forecast?latitude=32.79004&longitude=130.71618&daily=weathercode&timezone=Asia%2FTokyo";
        int weatherCode = -1;
        int weatherId = 0;

        try
        {
            using (WebClient client = new WebClient())
            {
                client.Encoding = Encoding.UTF8;
                string json = client.DownloadString(weatherUrl);
                Match codeMatch = Regex.Match(json, @"""weathercode"":\[(\d+)");
                if (codeMatch.Success)
                {
                    weatherCode = int.Parse(codeMatch.Groups[1].Value);
                    weatherId = GetWeatherIdFromCode(weatherCode);
                }
            }
        }
        catch
        {
            return ToShiftJis("天気コードの取得に失敗しました");
        }

        string temp = "未取得";
        string tempUrl = "https://api.openweathermap.org/data/2.5/weather?q=" + city + "&appid=" + apiKey + "&units=metric&lang=ja";

        try
        {
            using (WebClient client = new WebClient())
            {
                client.Encoding = Encoding.UTF8;
                string json = client.DownloadString(tempUrl);
                Match tempMatch = Regex.Match(json, @"""temp"":([-]?\d+(\.\d+)?)");
                if (tempMatch.Success)
                {
                    temp = tempMatch.Groups[1].Value + "℃";
                }
            }
        }
        catch
        {
            temp = "気温取得失敗";
        }

        string weatherName = GetWeatherNameFromId(weatherId);
        string result = string.Format("天気ID: {0}, 天気: {1}, 気温: {2}", weatherId, weatherName, temp);
        return ToShiftJis(result);
    }

    private static int GetWeatherIdFromCode(int code)
    {
        if (code == 0) return code;                    // 晴れ
        else if (code <= 3) return code;               // 曇り
        else if (code >= 45 && code <= 48) return code; // 霧
        else if (code >= 51 && code <= 67) return code; // 霧雨
        else if (code >= 71 && code <= 77) return code; // 雪
        else if (code >= 80 && code <= 82) return code; // 雨
        else if (code >= 95 && code <= 99) return code; // 雷雨
        else return 0;                              // 不明
    }

    private static string GetWeatherNameFromId(int id)
    {
        switch (id)
        {
            case 1: return "晴れ";
            case 2: return "曇り";
            case 3: return "霧";
            case 4: return "霧雨";
            case 5: return "雪";
            case 6: return "雨";
            case 7: return "雷雨";
            default: return "不明";
        }
    }

    private static string ToShiftJis(string text)
    {
        byte[] bytes = Encoding.GetEncoding("shift_jis").GetBytes(text);
        return Encoding.GetEncoding("shift_jis").GetString(bytes);
    }
}

using System;
using System.Text.RegularExpressions;

public static class Snippet
{
	public static System.Int64 WeatheridGet(ref System.String returnstring)
    {
        Match match = Regex.Match(returnstring, @"天気ID:\s*(\d+)");
        if (match.Success)
        {
            return Convert.ToInt64(match.Groups[1].Value);
        }
        else
        {
            return -1; // 見つからなかった場合のエラー値（必要に応じて変更可）
        }
    }
}

using System;
using System.Text.RegularExpressions;

public static class Snippet
{
	public static System.String WeatherstringGet(ref System.String returnstring)
    {
        // 「天気: 」の後ろに続く大分類（括弧前の文字列）だけを取得
        Match match = Regex.Match(returnstring, @"天気:\s*([^,]+)");
        if (match.Success)
        {
            return match.Groups[1].Value.Trim();
        }
        else
        {
            return ""; // 見つからなかった場合
        }
    }
}

using System;
using System.Text.RegularExpressions;

public static class Snippet
{
	public static System.Double WeatheridGet(ref System.String returnstring)
	{
		Match match = Regex.Match(returnstring, @"気温:\s*([0-9]+(?:\.[0-9]+)?)");
        if (match.Success)
        {
            return Convert.ToDouble(match.Groups[1].Value);
        }
        else
        {
            return -999.0; // エラー時のデフォルト値
        }
    }
}
